-- M2: organizations, machines, enrollment, agent sessions, and events.
--
-- IDs are UUIDs and timestamps are UTC, generated by the server (not the
-- database) so both backends store the same values.

CREATE TABLE organizations (
    id         UUID PRIMARY KEY NOT NULL,
    name       TEXT NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE machines (
    id               UUID PRIMARY KEY NOT NULL,
    organization_id  UUID NOT NULL REFERENCES organizations (id),
    name             TEXT NOT NULL,
    created_at       TIMESTAMPTZ NOT NULL,
    -- Set when an enrollment token is redeemed; NULL until then.
    enrolled_at      TIMESTAMPTZ,
    -- SHA-256 (hex) of the agent's long-lived credential.
    credential_hash  TEXT UNIQUE,
    agent_version    TEXT,
    facts            JSONB,
    facts_updated_at TIMESTAMPTZ,
    last_seen_at     TIMESTAMPTZ,
    UNIQUE (organization_id, name)
);

CREATE TABLE enrollment_tokens (
    id         UUID PRIMARY KEY NOT NULL,
    machine_id UUID NOT NULL REFERENCES machines (id) ON DELETE CASCADE,
    -- SHA-256 (hex) of the one-time token; the token itself is not stored.
    token_hash TEXT NOT NULL UNIQUE,
    created_at TIMESTAMPTZ NOT NULL,
    expires_at TIMESTAMPTZ NOT NULL,
    used_at    TIMESTAMPTZ
);

CREATE TABLE agent_sessions (
    id                UUID PRIMARY KEY NOT NULL,
    machine_id        UUID NOT NULL REFERENCES machines (id) ON DELETE CASCADE,
    agent_version     TEXT NOT NULL,
    connected_at      TIMESTAMPTZ NOT NULL,
    last_heartbeat_at TIMESTAMPTZ NOT NULL,
    disconnected_at   TIMESTAMPTZ,
    disconnect_reason TEXT
);

CREATE INDEX agent_sessions_open ON agent_sessions (machine_id)
    WHERE disconnected_at IS NULL;

CREATE TABLE events (
    id              UUID PRIMARY KEY NOT NULL,
    organization_id UUID NOT NULL REFERENCES organizations (id),
    machine_id      UUID REFERENCES machines (id) ON DELETE SET NULL,
    kind            TEXT NOT NULL,
    data            JSONB NOT NULL,
    created_at      TIMESTAMPTZ NOT NULL
);

CREATE INDEX events_machine ON events (machine_id, created_at);
